                n += 1
                st = [(i, j)]
                seen.add((i, j))
                while st:
                    a, b = st.pop()
                    for c, d in ((a + 1, b), (a - 1, b), (a, b + 1), (a, b - 1)):
                        if 0 <= c < h and 0 <= d < w and g[c][d] == 1 and (c, d) not in seen:
                            seen.add((c, d))
                            st.append((c, d))
    return n

def solve(t):
    st = []
    for x in t:
        if x in ('+', '-', '*', '/'):
            b = st.pop()
            a = st.pop()
            if x == '+':
                st.append(a + b)
            elif x == '-':
                st.append(a - b)
            elif x == '*':
                st.append(a * b)
            else:
                q = abs(a) // abs(b)
                st.append(q if (a < 0) == (b < 0) else -q)
        else:
            st.append(int(x))
    return st[0]

