def solve(s):
    """Return True if brackets are balanced and properly nested.
    Considers (), [], {}. Ignores all other characters.
    If the input is not a string, treat it as having no brackets and return True.
    """
    if not isinstance(s, str):
        return True
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    openings = set(pairs.values())
    for ch in s:
        if ch in openings:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

