def solve(grid):
    """Count islands in a binary grid (batch 2 version).
    Islands are groups of adjacent 1s (4-directional). Returns 0 for empty grid.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    if cols == 0:
        return 0
    visited = [[False]*cols for _ in range(rows)]
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < rows and 0 <= nj < cols and not visited[ni][nj] and grid[ni][nj]==1:
                    stack.append((ni,nj))
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j]==1 and not visited[i][j]:
                count += 1
                dfs(i,j)
    return count

