def solve(grid):
    """Count islands in a binary grid that may be jagged (rows of varying lengths).
    4-directional connectivity. Empty grid or rows with no columns return 0.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = []
    for r in range(rows):
        visited.append([False] * len(grid[r]))
    def in_bounds(r, c):
        return 0 <= r < rows and 0 <= c < len(grid[r])
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr, nc = i+dr, j+dc
                if in_bounds(nr, nc) and not visited[nr][nc] and grid[nr][nc] == 1:
                    stack.append((nr, nc))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                dfs(i, j)
    return count

